rows=[]
for filename in ['paper_D.tex','unresolved_D.tex']:
    data=(root/filename).read_text()
    for m in re.finditer(r'\\label\{(D:[^}]+)\}',data):
        key=m.group(1)
        if key not in summaries:continue
        statement,status,deps,pages,notes=summaries[key]
        line=data[:m.start()].count('\n')+1
        rows.append([key,statement,status,f'parts/D/{filename}:{line}',deps,pages,notes])
assert len({row[0] for row in rows})==len(rows), 'Duplicate statement labels in Part D'
with (root/'results_D.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['id','statement','status','where_proved','depends_on','manuscript_pages','notes']);w.writerows(rows)
